    static var identifiers: [String] { entries.map(\.id) }

    // Every registered suite uses explicit assertion-case custody. Admission
    // is not execution evidence; exact-source guardian receipts qualify each run.
    static var guardianCatalog: [String: [String]] {
        caseIDs.filter { ["m1", "m3", "practical-m3", "m2", "practical-m2", "discovery-bootstrap", "discovery-caller", "m4", "m6", "runtime-guardian", "runtime-custody", "policy-wire", "policy-binding", "policy-projection", "release-identity", "policy-input", "policy-transport", "closed-runner", "identity-history", "policy-authority", "policy-snapshot", "policy-catalog", "policy-catalog-session", "publisher-policy", "runtime-ownership", "discovery-spawn", "body1", "body2", "body3", "body4", "v3-preflight", "v4-preflight", "beta-v02-chooser", "beta-v02-device-drift", "beta-v03", "beta-v04", "beta-v05", "beta-v06", "beta-v07", "beta-v08", "beta-v09"].contains($0.key) }
    }

    static func discovery() throws -> [[String: Any]] {
        let registered = entries
        guard Set(registered.map(\.id)).count == registered.count,
              Set(caseIDs.keys) == Set(registered.map(\.id)),
              registered.allSatisfy({ !$0.cases.isEmpty && Set($0.cases).count == $0.cases.count }) else {
            throw InvalidSelection()
        }
        return registered.map { ["id": $0.id, "cases": $0.cases] }
    }

    static func selectedID(argument: String) -> String? {
        let prefix = "--ci-suite="
        guard argument.hasPrefix(prefix) else { return nil }
        let id = String(argument.dropFirst(prefix.count))
        return identifiers.contains(id) ? id : nil
    }

    static func run(
        ids: [String], app: String,
        onPass: (String) -> Void,
        onFailure: (String) -> Void
    ) throws -> Bool {
        _ = try discovery()
        let registered = entries
        guard !ids.isEmpty, Set(ids).count == ids.count,
              Set(registered.map(\.id)).count == registered.count,
              ids.allSatisfy({ id in registered.contains { $0.id == id } }),
              ProcessInfo.processInfo.environment["SHADOW_SYNC_BODY1_TEST"] == nil else {
            throw InvalidSelection()
        }
        var complete = true
        for id in ids {
            let entry = registered.first { $0.id == id }!
            let expected = Set(entry.cases)
            var passed: Set<String> = []
            var invalidReport = false
            do {
                try entry.run(app) { name in
                    // Timing is diagnostic; it is not part of a stable case ID.
                    let normalized = name.replacingOccurrences(
                        of: #" \[\d+ ms\]$"#, with: "", options: .regularExpression)
                    guard !normalized.isEmpty, normalized == normalized.trimmingCharacters(in: .whitespacesAndNewlines),
                          !normalized.unicodeScalars.contains(where: { $0.value < 32 || $0.value == 127 }),
                          expected.contains(normalized),
                          passed.insert(normalized).inserted else {
                        invalidReport = true
                        return
                    }
                    onPass(id + "/" + normalized)
                }
                guard passed == expected, !invalidReport else { throw InvalidCompletion() }
            } catch {
                complete = false
                // Independent suites still execute; a failed suite never becomes
                // successful because another suite or a later retry succeeded.
                onFailure(id + ": " + Redactor.sanitize(String(describing: error)))
            }
        }
        return complete
    }

    private struct InvalidSelection: Error {}
    private struct InvalidCompletion: Error {}
}
